      eraPref:{sengoku:0.01,azuchi:0.01,edo:0.01,jomon:0.01,yayoi:0.01,asuka:0.01,nara:0.01,heian:0.01,kamakura:0.01,muromachi:0.01,edo_late:0.01,bakumatsu:0.01,meiji:0.01,taisho_showa:0.01,gendai:0.01,sekai_kodai:0.01,daikoukai:0.01,shimin_kakumei:0.01,sangyo_teikoku:0.01,ww1:0.01,kiyomori:0.01,godaigo:0.01,soun:0.01,rikyu:0.01,kakuei:3,confucius:0.01,socrates:0.01,shaka:0.01,alexander:0.01,caesar:0.01,qin:0.01,muhammad:0.01,gandhi:0.01,washington:0.01,churchill:0.01,kennedy:0.01,ino:0.01,fukuzawa:0.01,montesquieu:0.01},
