      uniqueSkill:{id:"uq_sanken",icon:"⚖️",name:"三権分立",desc:"論戦（合戦）で「公正」の采配が決まると、権力の濫用を防ぐ理がさえわたり戦果がさらに増す（偉人固有）",fx:{battleStat:"seiji"}},
      sceneImgs:["assets/scene_montesquieu.jpg","assets/scene_montesquieu.jpg","assets/scene_montesquieu.jpg","assets/scene_montesquieu.jpg","assets/scene_montesquieu.jpg"],
      statLabels:{buyu:"勇",chiryaku:"学",seiji:"公",ninbo:"徳"},
